import { useRender } from '@base-ui/react/use-render';
import { Check, ChevronLeft, ChevronRight, CircleAlert, Eye, History, PanelLeft, PanelRight, Play, RotateCw, Sparkle, WifiOff, Zap } from 'lucide-react';
import { useId, useLayoutEffect, useRef, useState, type ComponentProps, type KeyboardEvent, type ReactElement, type ReactNode, type RefObject } from 'react';
import { cn } from '../lib/cn';
import { useControllable } from '../lib/use-controllable';
import { CountBadge } from './badge';
import type { BreadcrumbItem } from './breadcrumb';
import { Button, IconButton } from './button';
import { pluralRu } from './canvas-check';
import type { CanvasPerson } from './canvas-node';
import { Avatar, AvatarGroup } from './card';
import { Tooltip } from './popover';
import { Skeleton } from './progress';

/** Below this editor width the palette and the inspector open over the canvas, not beside it. */
const NARROW_EDITOR = 900;

export type CanvasSaveState = 'saved' | 'saving' | 'offline' | 'failed';

export interface CanvasEditorProps extends Omit<ComponentProps<'section'>, 'title' | 'children'> {
  /** Path to the graph, without the graph itself: «Автоматизации». */
  breadcrumbs: readonly BreadcrumbItem[];
  /** Graph name, the current crumb: «Заявка из Telegram → сделка». */
  title: string;
  /** Version chip: «Черновик · опубликована v7». */
  version?: string;
  /** Text of the saved state, announced politely: «сохранено только что». */
  saved?: string;
  /** offline and failed replace the text with a chip and switch «Запустить» and «Опубликовать» off. */
  saveState?: CanvasSaveState;
  /** «Повторить» next to «Не сохранено». */
  onRetrySave?: () => void;
  /** Problems that block publishing: «Опубликовать» shows the count and opens them via onValidate. */
  errors?: number;
  /** Who has the graph open: avatars 28, up to three and «+N». */
  people?: readonly Omit<CanvasPerson, 'editing'>[];
  onHistory?: () => void;
  onValidate?: () => void;
  onRun?: () => void;
  onPublish?: () => void;
  /** Extra header controls before «История». */
  actions?: ReactNode;
  /** Left zone 224: usually `<StepPalette>`. */
  palette?: ReactNode;
  /** Right zone 288: the inspector of the selection. */
  inspector?: ReactNode;
  paletteOpen?: boolean;
  /** Without it the palette is open on a wide editor and folded on a narrow one. */
  defaultPaletteOpen?: boolean;
  onPaletteOpenChange?: (open: boolean) => void;
  inspectorOpen?: boolean;
  defaultInspectorOpen?: boolean;
  onInspectorOpenChange?: (open: boolean) => void;
  /** The canvas; it takes all the width the zones leave. */
  children: ReactNode;
}

function ZoneToggle({
  label,
  open,
  icon,
  onToggle,
  ref,
}: {
  label: string;
  open: boolean;
  icon: ReactNode;
  onToggle: () => void;
  ref: RefObject<HTMLButtonElement | null>;
}) {
  return (
    <Tooltip content={open ? `Скрыть: ${label.toLowerCase()}` : `Показать: ${label.toLowerCase()}`}>
      <IconButton ref={ref} aria-label={label} aria-pressed={open} size="sm" icon={icon} onClick={onToggle} />
    </Tooltip>
  );
}

function Zone({
  label,
  side,
  overlay,
  toggle,
  onClose,
  children,
}: {
  label: string;
  side: 'left' | 'right';
  overlay: boolean;
  toggle: RefObject<HTMLButtonElement | null>;
  onClose: () => void;
  children: ReactNode;
}) {
  const ref = useRef<HTMLElement>(null);
  // opened from its toggle over the canvas: take the focus so Tab and Esc start here
  useLayoutEffect(() => {
    if (overlay && document.activeElement === toggle.current) ref.current?.focus();
  }, [overlay, toggle]);

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    // portalled popups of the zone bubble here through React: only Esc from the zone itself closes it
    if (!overlay || event.key !== 'Escape' || event.defaultPrevented || !event.currentTarget.contains(event.target as Node)) return;
    event.stopPropagation();
    onClose();
    toggle.current?.focus();
  };

  return (
    <aside
      ref={ref}
      aria-label={label}
      data-overlay={overlay ? '' : undefined}
      tabIndex={overlay ? -1 : undefined}
      onKeyDown={onKeyDown}
      className={cn(
        'flex shrink-0 flex-col overflow-y-auto bg-surface-1 outline-none',
        side === 'left' ? 'w-56 border-r border-separator' : 'w-72 border-l border-separator',
        overlay && cn('absolute inset-y-0 z-10 max-w-[calc(100%-48px)] shadow-overlay', side === 'left' ? 'left-0' : 'right-0'),
      )}
    >
      {children}
    </aside>
  );
}

function Crumb({ item, className, children, ...props }: { item: BreadcrumbItem; className: string; children: ReactNode; 'aria-label'?: string }) {
  return useRender({ defaultTagName: 'a', render: item.render, props: { href: item.href, className, children, ...props } });
}

/** A switched-off action keeps its place, its focus and a tooltip saying why. */
function Gate({ reason, children }: { reason: string | undefined; children: ReactElement }) {
  if (!reason) return children;
  return (
    <Tooltip content={reason}>
      <span className="inline-flex">{children}</span>
    </Tooltip>
  );
}

const crumbLink =
  'kv-pressable inline-flex h-6 min-w-0 items-center rounded-full px-1 text-fg-3 decoration-1 underline-offset-3 [--kv-press-scale:1] hover:text-fg-1 hover:underline active:bg-fill-2';
// Header steps, by the editor's own width: version → save text → «История» to an icon → avatars → check and run to icons.
const narrowHistory = '@max-[999px]:gap-0 @max-[999px]:px-2';
const narrowCheckRun = '@max-[829px]:gap-0 @max-[829px]:px-2';

/** Editor shell: header with path, version and actions over three zones — palette | canvas | inspector. */
export function CanvasEditor({
  breadcrumbs,
  title,
  version,
  saved,
  saveState = 'saved',
  onRetrySave,
  errors = 0,
  people,
  onHistory,
  onValidate,
  onRun,
  onPublish,
  actions,
  palette,
  inspector,
  paletteOpen,
  defaultPaletteOpen,
  onPaletteOpenChange,
  inspectorOpen,
  defaultInspectorOpen = true,
  onInspectorOpenChange,
  className,
  children,
  ...props
}: CanvasEditorProps) {
  const rootRef = useRef<HTMLElement>(null);
  const paletteToggle = useRef<HTMLButtonElement>(null);
  const inspectorToggle = useRef<HTMLButtonElement>(null);
  const reasonId = useId();
  const [narrow, setNarrow] = useState(false);
  // undefined: nobody chose yet, the width decides
  const [paletteChoice, setPaletteChoice] = useControllable<boolean | undefined>(paletteOpen, defaultPaletteOpen, (next) => {
    if (next !== undefined) onPaletteOpenChange?.(next);
  });
  const [showInspector, setShowInspector] = useControllable(inspectorOpen, defaultInspectorOpen, onInspectorOpenChange);
  const showPalette = paletteChoice ?? !narrow;

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    // 0 is a box that is not laid out (a hidden tab, jsdom): keep the wide layout
    const measure = () => setNarrow(root.clientWidth > 0 && root.clientWidth < NARROW_EDITOR);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    return () => observer.disconnect();
  }, []);

  const parent = breadcrumbs[breadcrumbs.length - 1];
  const blocked =
    saveState === 'offline'
      ? 'Нет сети: запуск и публикация вернутся вместе со связью'
      : saveState === 'failed'
        ? 'Правки не сохранены: сначала повторите сохранение'
        : undefined;
  const publishNote =
    blocked ?? (errors > 0 ? `${errors} ${pluralRu(errors, ['ошибка мешает', 'ошибки мешают', 'ошибок мешают'])} публиковать — откроется список проблем` : undefined);

  return (
    <section
      ref={rootRef}
      data-slot="canvas-editor"
      aria-label={title}
      className={cn('flex min-h-0 flex-col overflow-hidden bg-surface-1', className)}
      {...props}
    >
      {/* Wraps into two rows rather than letting anything overlap; the steps above keep one row down to ~650px. */}
      <header className="@container flex min-h-14 shrink-0 flex-wrap items-center gap-x-4 gap-y-2 border-b border-separator py-2 pr-3 pl-4">
        <div className="flex min-w-0 grow basis-[300px] items-center gap-2">
          <nav aria-label="Путь" className="flex min-w-0 items-center text-body-sm">
            {parent ? (
              <Crumb
                item={parent}
                aria-label={`Назад: ${parent.label}`}
                className="kv-pressable -ml-2 grid size-8 shrink-0 place-items-center rounded-full text-fg-2 hover:bg-fill-1 @min-[640px]:hidden [&_svg]:size-4 [&_svg]:stroke-[1.75]"
              >
                <ChevronLeft aria-hidden />
              </Crumb>
            ) : null}
            <ol className="flex min-w-0 items-center gap-1">
              {breadcrumbs.map((item) => (
                <li key={item.label} className="flex min-w-0 shrink-[100] items-center gap-1 @max-[639px]:hidden">
                  <Crumb item={item} className={crumbLink}>
                    <span className="max-w-40 truncate">{item.label}</span>
                  </Crumb>
                  <ChevronRight aria-hidden className="size-4 shrink-0 stroke-[1.75] text-fg-4" />
                </li>
              ))}
              <li className="flex min-w-[120px] items-center px-1">
                <span aria-current="page" title={title} className="min-w-[120px] truncate font-semibold text-fg-1">
                  {title}
                </span>
              </li>
            </ol>
          </nav>
          {version ? (
            <span className="h-[22px] shrink-0 rounded-xs bg-fill-2 px-2 text-caption/[22px] font-medium whitespace-nowrap text-fg-2 @max-[1279px]:hidden">
              {version}
            </span>
          ) : null}
          <span
            role="status"
            className={cn('flex min-w-0 items-center text-caption whitespace-nowrap text-fg-3', (saveState === 'saved' || saveState === 'saving') && '@max-[1079px]:hidden')}
          >
            {saveState === 'offline' ? (
              <span className="flex h-6 min-w-0 items-center gap-1.5 rounded-xs bg-warning-soft px-2 font-medium text-warning-soft-fg">
                <WifiOff aria-hidden className="size-3 shrink-0 stroke-[2.5]" />
                <span className="truncate">Нет сети · правки ждут</span>
              </span>
            ) : saveState === 'failed' ? (
              <span className="flex h-6 min-w-0 items-center rounded-xs bg-danger-soft px-2 font-medium text-danger-soft-fg">
                <span className="truncate">Не сохранено</span>
              </span>
            ) : saveState === 'saving' ? (
              'сохраняем…'
            ) : (
              saved
            )}
          </span>
          {saveState === 'failed' && onRetrySave ? (
            <Button variant="ghost" size="sm" leadingIcon={<RotateCw />} className="bg-fill-2 hover:bg-fill-3 @min-[640px]:[&>svg]:hidden @max-[639px]:gap-0 @max-[639px]:px-2" onClick={onRetrySave}>
              <span className="@max-[639px]:sr-only">Повторить</span>
            </Button>
          ) : null}
        </div>
        <div className="ml-auto flex flex-wrap items-center justify-end gap-2">
          {people && people.length > 0 ? (
            <AvatarGroup max={3} size={28} className="-space-x-1.5! pr-2 @max-[899px]:hidden">
              {people.map((person) => (
                <Avatar
                  key={person.name}
                  name={person.name}
                  size={28}
                  className="text-fg-1!"
                  style={{ backgroundColor: `color-mix(in oklab, ${person.color} 22%, var(--color-surface-1))` }}
                />
              ))}
            </AvatarGroup>
          ) : null}
          {palette ? (
            <ZoneToggle ref={paletteToggle} label="Палитра шагов" open={showPalette} icon={<PanelLeft />} onToggle={() => setPaletteChoice(!showPalette)} />
          ) : null}
          {inspector ? (
            <ZoneToggle ref={inspectorToggle} label="Инспектор" open={showInspector} icon={<PanelRight />} onToggle={() => setShowInspector(!showInspector)} />
          ) : null}
          {actions}
          {onHistory ? (
            <Button variant="ghost" size="sm" leadingIcon={<History />} className={narrowHistory} onClick={onHistory}>
              <span className="@max-[999px]:sr-only">История</span>
            </Button>
          ) : null}
          {onValidate ? (
            <Button variant="ghost" size="sm" leadingIcon={<Check />} className={narrowCheckRun} onClick={onValidate}>
              <span className="@max-[829px]:sr-only">Проверить</span>
            </Button>
          ) : null}
          {onRun ? (
            <Gate reason={blocked}>
              <Button
                variant="secondary"
                size="sm"
                leadingIcon={<Play className="fill-current" />}
                className={narrowCheckRun}
                disabled={blocked !== undefined}
                focusableWhenDisabled
                aria-describedby={blocked ? reasonId : undefined}
                onClick={onRun}
              >
                <span className="@max-[829px]:sr-only">Запустить</span>
              </Button>
            </Gate>
          ) : null}
          {onPublish ? (
            <Gate reason={blocked}>
              <Button
                variant="primary"
                size="sm"
                disabled={blocked !== undefined}
                focusableWhenDisabled
                aria-describedby={publishNote ? `${reasonId}-publish` : undefined}
                onClick={errors > 0 ? onValidate : onPublish}
              >
                Опубликовать
                {errors > 0 ? <CountBadge aria-hidden count={errors} className="ml-1.5 shadow-none" /> : null}
              </Button>
            </Gate>
          ) : null}
          <span id={reasonId} hidden>
            {blocked}
          </span>
          <span id={`${reasonId}-publish`} hidden>
            {publishNote}
          </span>
        </div>
      </header>
      <div className="relative flex min-h-0 flex-1">
        {palette && showPalette ? (
          <Zone label="Палитра шагов" side="left" overlay={narrow} toggle={paletteToggle} onClose={() => setPaletteChoice(false)}>
            {palette}
          </Zone>
        ) : null}
        <div role="region" aria-label="Канвас" className="relative min-w-0 flex-1 overflow-hidden">
          {children}
        </div>
        {inspector && showInspector ? (
          <Zone label="Инспектор" side="right" overlay={narrow} toggle={inspectorToggle} onClose={() => setShowInspector(false)}>
            {inspector}
          </Zone>
        ) : null}
      </div>
    </section>
  );
}

/* ---------- Canvas states ---------- */

export type CanvasStateKind = 'empty' | 'loading' | 'error';

export interface CanvasStateProps extends Omit<ComponentProps<'div'>, 'title' | 'children'> {
  /** empty — the first step; loading — a skeleton of the saved layout; error — the graph did not open. */
  kind: CanvasStateKind;
  /** Overrides «Начните с триггера» / «Загружаем граф…» / «Граф не открылся». */
  title?: string;
  /** Overrides the line under the title. */
  description?: string;
  /** empty: «Добавить шаг» (Enter on the canvas does the same). */
  onAddStep?: () => void;
  /** empty: «Собрать с Нордой». */
  onBuildWithNorda?: () => void;
  /** error: «Повторить». */
  onRetry?: () => void;
  /** error: the version to fall back to, «v7» → «Открыть версию v7». */
  version?: string;
  onOpenVersion?: () => void;
}

const stateTile = 'grid size-11 shrink-0 place-items-center rounded-md [&_svg]:size-5 [&_svg]:stroke-2';

function SkeletonNode({ line, sub }: { line: string; sub: string }) {
  return (
    <div className="flex h-12 w-32 items-center gap-2 rounded-md bg-surface-1 px-3 shadow-[0_0_0_1px_var(--color-hairline)]">
      <Skeleton shape="rect" className="size-6 rounded-[7px]" />
      <div className="flex flex-col gap-[5px]">
        <Skeleton className={cn('h-2 rounded-[4px]', line)} />
        <Skeleton className={cn('h-1.5 rounded-[3px]', sub)} />
      </div>
    </div>
  );
}

/**
 * What the canvas shows while the graph is not there: empty, loading or failed to open.
 * No position of its own: it fills and centres in whatever holds it — the engine's empty slot or an overlay over the canvas.
 */
export function CanvasState({
  kind,
  title,
  description,
  onAddStep,
  onBuildWithNorda,
  onRetry,
  version,
  onOpenVersion,
  className,
  ...props
}: CanvasStateProps) {
  const shell = 'flex size-full flex-col items-center justify-center gap-4 p-6 text-center';

  if (kind === 'loading') {
    return (
      <div data-slot="canvas-state" data-kind={kind} role="status" aria-busy className={cn(shell, 'gap-0', className)} {...props}>
        <span className="sr-only">{title ?? 'Загружаем граф…'}</span>
        <SkeletonNode line="w-16" sub="w-10" />
        <span aria-hidden className="h-10 w-0.5 bg-fill-3" />
        <SkeletonNode line="w-14" sub="w-11" />
        <span aria-hidden className="h-10 w-0.5 bg-fill-3" />
        <SkeletonNode line="w-[70px]" sub="w-9" />
      </div>
    );
  }

  const error = kind === 'error';
  return (
    <div data-slot="canvas-state" data-kind={kind} role={error ? 'alert' : undefined} className={cn(shell, error && 'bg-surface-2', className)} {...props}>
      {error ? (
        <span aria-hidden className={cn(stateTile, 'bg-danger-soft text-danger-soft-fg')}>
          <CircleAlert />
        </span>
      ) : (
        <span
          aria-hidden
          className={cn(
            stateTile,
            'bg-surface-1 text-chart-5 shadow-[0_0_0_1px_var(--color-hairline),0_1px_2px_color-mix(in_oklab,var(--color-fg-1)_5%,transparent)]',
          )}
        >
          <Zap />
        </span>
      )}
      <div className="flex flex-col items-center gap-1">
        <h3 className="text-body-md font-semibold text-fg-1">{title ?? (error ? 'Граф не открылся' : 'Начните с триггера')}</h3>
        <p className={cn('text-body-xs text-fg-2', error ? 'max-w-[300px]' : 'max-w-[280px]')}>
          {description ?? (error ? 'Сервер не ответил. Ваши правки целы — они сохранены в черновике.' : 'Что запускает автоматизацию: сообщение, расписание или вебхук?')}
        </p>
      </div>
      {error ? (
        onRetry || onOpenVersion ? (
          <div className="flex flex-wrap items-center justify-center gap-3">
            {onRetry ? (
              <Button variant="outline" size="sm" className="bg-surface-1 px-3" onClick={onRetry}>
                Повторить
              </Button>
            ) : null}
            {onOpenVersion ? (
              <Button variant="link" size="sm" onClick={onOpenVersion}>
                {version ? `Открыть версию ${version}` : 'Открыть опубликованную версию'}
              </Button>
            ) : null}
          </div>
        ) : null
      ) : onAddStep || onBuildWithNorda ? (
        <div className="flex flex-wrap items-center justify-center gap-2">
          {onAddStep ? (
            <Button variant="outline" size="sm" className="bg-surface-1 pr-2.5 pl-3" onClick={onAddStep}>
              Добавить шаг
              <span aria-hidden className="ml-1.5 grid h-[18px] place-items-center rounded-[5px] bg-fill-2 px-[5px] font-mono text-[11px]/[14px] font-medium text-fg-3">
                ↵
              </span>
            </Button>
          ) : null}
          {onBuildWithNorda ? (
            <Button variant="soft" size="sm" leadingIcon={<Sparkle />} className="px-3 [&_svg]:size-3.5" onClick={onBuildWithNorda}>
              Собрать с Нордой
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export interface CanvasReadonlyBarProps extends ComponentProps<'div'> {
  /** «Попросить доступ»; without it the bar only says why nothing can be changed. */
  onRequestAccess?: () => void;
}

/** Plaque over the top of a read-only canvas: ports, palette and toolbars are hidden, view, search and comments stay. */
export function CanvasReadonlyBar({ onRequestAccess, className, children = 'Только просмотр', ...props }: CanvasReadonlyBarProps) {
  return (
    <div
      data-slot="canvas-readonly-bar"
      className={cn(
        'flex h-control-lg items-center justify-between gap-2 rounded-md bg-surface-1 pr-1.5 pl-3.5 shadow-[0_0_0_1px_var(--color-border)]',
        className,
      )}
      {...props}
    >
      <span className="flex min-w-0 items-center gap-2 text-body-xs font-medium text-fg-1">
        <Eye aria-hidden className="size-4 shrink-0 stroke-[1.75] text-fg-2" />
        <span className="truncate">{children}</span>
      </span>
      {onRequestAccess ? (
        <Button variant="ghost" size="sm" className="bg-fill-2 px-3 hover:bg-fill-3" onClick={onRequestAccess}>
          Попросить доступ
        </Button>
      ) : null}
    </div>
  );
}

import type { CanvasEdge, CanvasGraph, CanvasNode, CanvasPort, CanvasPortType } from './canvas-types';

/* ---------- Graph check ---------- */

export type CanvasProblemSeverity = 'error' | 'warning';

export type CanvasProblemKind = 'no-trigger' | 'cycle' | 'required-input' | 'unreachable' | 'open-branch' | 'broken-edge' | 'type-mismatch';

export interface CanvasProblem {
  /** Stable between runs of the same graph: kind plus the ids involved. */
  id: string;
  kind: CanvasProblemKind;
  /** error blocks publishing, warning does not. */
  severity: CanvasProblemSeverity;
  /** «Цикл без выхода». */
  title: string;
  /** What is wrong and how to fix it, with step names. */
  description: string;
  /** Steps to show: the first one gets the camera. */
  nodeIds: readonly string[];
  edgeId?: string;
  portId?: string;
}

export interface CheckGraphOptions<TData> {
  /** Step name in the messages; default — the node id. */
  label?: (node: CanvasNode<TData>) => string;
  /** Inputs that must be connected; default — ports marked `required`, the same ones the canvas draws in danger. */
  isRequired?: (node: CanvasNode<TData>, port: CanvasPort) => boolean;
}

/** Notes and groups are not steps: they never run and need no connections. */
const isStep = (node: CanvasNode<unknown>) => node.kind !== 'note' && node.kind !== 'group';

const typeNames: Record<CanvasPortType, string> = {
  flow: 'поток',
  text: 'текст',
  number: 'число',
  date: 'дата',
  boolean: 'да/нет',
  object: 'объект',
  list: 'список',
  tool: 'инструмент',
  memory: 'память',
  knowledge: 'знания',
};

/** Russian name of a port type: «текст», «число». */
export function portTypeName(type: CanvasPortType): string {
  return typeNames[type];
}

const capitalize = (text: string) => text.charAt(0).toUpperCase() + text.slice(1);

const plurals = new Intl.PluralRules('ru');

/** Russian noun for a count: `pluralRu(2, ['ошибка', 'ошибки', 'ошибок'])` → «ошибки». */
export function pluralRu(count: number, [one, few, many]: readonly [one: string, few: string, many: string]): string {
  const rule = plurals.select(count);
  return rule === 'one' ? one : rule === 'few' ? few : many;
}

// Anything becomes text without loss, so number, date and yes/no flow into text silently.
const intoText: ReadonlySet<CanvasPortType> = new Set(['number', 'date', 'boolean']);

function compatibility(from: CanvasPortType | undefined, to: CanvasPortType | undefined): 'ok' | 'convert' | 'wrong' {
  if (!from || !to || from === to) return 'ok';
  if (from === 'flow' || to === 'flow') return 'wrong';
  if (to === 'text' && intoText.has(from)) return 'ok';
  return 'convert';
}

/** Strongly connected components (Tarjan), each in discovery order. */
function components(ids: readonly string[], next: ReadonlyMap<string, readonly string[]>): string[][] {
  const index = new Map<string, number>();
  const low = new Map<string, number>();
  const stack: string[] = [];
  const onStack = new Set<string>();
  const result: string[][] = [];
  let counter = 0;

  const visit = (id: string) => {
    index.set(id, counter);
    low.set(id, counter);
    counter += 1;
    stack.push(id);
    onStack.add(id);
    for (const target of next.get(id) ?? []) {
      if (!index.has(target)) {
        visit(target);
        low.set(id, Math.min(low.get(id) ?? 0, low.get(target) ?? 0));
      } else if (onStack.has(target)) {
        low.set(id, Math.min(low.get(id) ?? 0, index.get(target) ?? 0));
      }
    }
    if (low.get(id) !== index.get(id)) return;
    const component: string[] = [];
    let member: string | undefined;
    do {
      member = stack.pop();
      if (member === undefined) break;
      onStack.delete(member);
      component.push(member);
    } while (member !== id);
    result.push(component);
  };

  for (const id of ids) if (!index.has(id)) visit(id);
  return result;
}

/** One loop through the component from its first step, to name it «А → Б → А». */
function loopPath(start: string, members: ReadonlySet<string>, next: ReadonlyMap<string, readonly string[]>): string[] {
  const path: string[] = [];
  const seen = new Set<string>();
  const walk = (id: string): boolean => {
    path.push(id);
    seen.add(id);
    for (const target of next.get(id) ?? []) {
      if (target === start) return true;
      if (members.has(target) && !seen.has(target) && walk(target)) return true;
    }
    path.pop();
    return false;
  };
  walk(start);
  return path;
}

/**
 * Finds what breaks a run before it starts: cycles with no way out, empty required inputs, steps the trigger never
 * reaches, branches left open after a fork, edges to missing ports and data of the wrong type. Errors come first.
 */
export function checkGraph<TData>(graph: CanvasGraph<TData>, options: CheckGraphOptions<TData> = {}): CanvasProblem[] {
  const { label = (node: CanvasNode<TData>) => node.id, isRequired = (_node: CanvasNode<TData>, port: CanvasPort) => port.required === true } = options;
  const problems: CanvasProblem[] = [];
  const steps = graph.nodes.filter((node) => isStep(node) && !node.disabled);
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const name = (id: string) => {
    const node = byId.get(id);
    return node ? label(node) : id;
  };
  const portOf = (node: CanvasNode<TData> | undefined, id: string) => node?.ports.find((port) => port.id === id);

  // Edges that point at real ports in the right direction; the rest are broken.
  const edges: CanvasEdge[] = [];
  for (const edge of graph.edges) {
    const source = portOf(byId.get(edge.source), edge.sourcePort);
    const target = portOf(byId.get(edge.target), edge.targetPort);
    if (source?.direction === 'out' && target?.direction === 'in') {
      edges.push(edge);
      continue;
    }
    problems.push({
      id: `broken-edge:${edge.id}`,
      kind: 'broken-edge',
      severity: 'error',
      title: 'Связь никуда не ведёт',
      description: `Связь «${name(edge.source)}» → «${name(edge.target)}» держится за порт, которого нет. Удалите её и протяните заново.`,
      nodeIds: [edge.source, edge.target].filter((id) => byId.has(id)),
      edgeId: edge.id,
    });
  }

  const next = new Map<string, string[]>();
  for (const edge of edges) next.set(edge.source, [...(next.get(edge.source) ?? []), edge.target]);

  if (steps.length && !steps.some((node) => node.kind === 'trigger')) {
    problems.push({
      id: 'no-trigger',
      kind: 'no-trigger',
      severity: 'error',
      title: 'Нет триггера',
      description: 'Граф ничто не запускает. Добавьте триггер: сообщение, расписание или вебхук.',
      nodeIds: [],
    });
  }

  for (const component of components(
    steps.map((node) => node.id),
    next,
  )) {
    const members = new Set(component);
    const [only] = component;
    if (component.length === 1 && only !== undefined && !(next.get(only) ?? []).includes(only)) continue;
    const exits = component.some((id) => {
      const kind = byId.get(id)?.kind;
      return (kind === 'condition' || kind === 'loop') && (next.get(id) ?? []).some((target) => !members.has(target));
    });
    if (exits) continue;
    const first = steps.find((node) => members.has(node.id))?.id ?? component[0] ?? '';
    const path = loopPath(first, members, next);
    const ordered = [...path, ...component.filter((id) => !path.includes(id))];
    problems.push({
      id: `cycle:${[...component].sort().join(',')}`,
      kind: 'cycle',
      severity: 'error',
      title: 'Цикл без выхода',
      description: `${[...path, first].map(name).join(' → ')}. Добавьте условие, которое выводит из цикла, например «не больше 3 раз».`,
      nodeIds: ordered,
    });
  }

  for (const node of steps) {
    for (const port of node.ports) {
      if (port.direction !== 'in' || !isRequired(node, port)) continue;
      if (edges.some((edge) => edge.target === node.id && edge.targetPort === port.id)) continue;
      problems.push({
        id: `required-input:${node.id}:${port.id}`,
        kind: 'required-input',
        severity: 'error',
        title: 'Пустой обязательный вход',
        description: `«${label(node)}» ждёт «${port.label ?? port.id}», но к нему ничего не подключено.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  const triggers = steps.filter((node) => node.kind === 'trigger');
  if (triggers.length) {
    const reached = new Set<string>();
    const queue = triggers.map((node) => node.id);
    for (let id = queue.shift(); id !== undefined; id = queue.shift()) {
      if (reached.has(id)) continue;
      reached.add(id);
      queue.push(...(next.get(id) ?? []));
    }
    for (const node of steps) {
      if (reached.has(node.id)) continue;
      problems.push({
        id: `unreachable:${node.id}`,
        kind: 'unreachable',
        severity: 'warning',
        title: 'Шаг не запустится',
        description: `До «${label(node)}» не доходит ни одна связь от триггера. Подключите его или удалите.`,
        nodeIds: [node.id],
      });
    }
  }

  for (const node of steps) {
    const outs = node.ports.filter((port) => port.direction === 'out' && (port.type ?? 'flow') === 'flow');
    if (outs.length < 2) continue;
    const used = outs.filter((port) => edges.some((edge) => edge.source === node.id && edge.sourcePort === port.id));
    if (!used.length) continue;
    for (const port of outs) {
      if (used.includes(port)) continue;
      problems.push({
        id: `open-branch:${node.id}:${port.id}`,
        kind: 'open-branch',
        severity: 'warning',
        title: 'Ветка обрывается',
        description: `У «${label(node)}» ветка «${port.label ?? port.id}» никуда не ведёт — этот случай останется без действия.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  for (const edge of edges) {
    const from = portOf(byId.get(edge.source), edge.sourcePort)?.type;
    const to = portOf(byId.get(edge.target), edge.targetPort);
    const verdict = compatibility(from, to?.type);
    if (verdict === 'ok' || !from || !to?.type) continue;
    const wrong = verdict === 'wrong';
    problems.push({
      id: `type-mismatch:${edge.id}`,
      kind: 'type-mismatch',
      severity: wrong ? 'error' : 'warning',
      title: wrong ? 'Данные вместо шага' : `${capitalize(typeNames[from])} идёт в ${typeNames[to.type]}`,
      description: wrong
        ? `Связь «${name(edge.source)}» → «${name(edge.target)}» соединяет порядок шагов с данными. Подключите её к порту того же вида.`
        : `«${to.label ?? to.id}» получает ${typeNames[from]} — вставить конвертер «${typeNames[from]} → ${typeNames[to.type]}»?`,
      nodeIds: [edge.target, edge.source],
      edgeId: edge.id,
      portId: to.id,
    });
  }

  // Array#sort is stable: within a severity the order of discovery stays.
  return problems.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'error' ? -1 : 1));
}

/* ---------- Version diff ---------- */

export interface CanvasGraphDiff {
  nodes: { added: string[]; changed: string[]; removed: string[]; unchanged: string[] };
  edges: { added: string[]; removed: string[] };
}

export interface DiffGraphsOptions<TData> {
  /** Whether a step stayed the same; default compares kind, ports, parent, flags and data deeply. */
  same?: (before: CanvasNode<TData>, after: CanvasNode<TData>) => boolean;
}

function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;
  if (a instanceof Date || b instanceof Date) return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a).filter((key) => (a as Record<string, unknown>)[key] !== undefined);
  const keysB = Object.keys(b).filter((key) => (b as Record<string, unknown>)[key] !== undefined);
  return keysA.length === keysB.length && keysA.every((key) => deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key]));
}

// Position, size, selection and run status are view state: moving a step is not an edit of the automation.
const meaning = <TData>({ kind, ports, parentId, disabled, collapsed, data }: CanvasNode<TData>) => ({ kind, ports, parentId, disabled, collapsed, data });

/** What changed between two versions: steps added, changed, removed; edges added and removed. */
export function diffGraphs<TData>(before: CanvasGraph<TData>, after: CanvasGraph<TData>, options: DiffGraphsOptions<TData> = {}): CanvasGraphDiff {
  const { same = (a: CanvasNode<TData>, b: CanvasNode<TData>) => deepEqual(meaning(a), meaning(b)) } = options;
  const old = new Map(before.nodes.map((node) => [node.id, node]));
  const fresh = new Set(after.nodes.map((node) => node.id));
  const diff: CanvasGraphDiff = { nodes: { added: [], changed: [], removed: [], unchanged: [] }, edges: { added: [], removed: [] } };
  for (const node of after.nodes) {
    const previous = old.get(node.id);
    if (!previous) diff.nodes.added.push(node.id);
    else if (same(previous, node)) diff.nodes.unchanged.push(node.id);
    else diff.nodes.changed.push(node.id);
  }
  diff.nodes.removed = before.nodes.filter((node) => !fresh.has(node.id)).map((node) => node.id);
  const key = (edge: CanvasEdge) => `${edge.source}\u0000${edge.sourcePort}\u0000${edge.target}\u0000${edge.targetPort}`;
  const oldEdges = new Set(before.edges.map(key));
  const newEdges = new Set(after.edges.map(key));
  diff.edges.added = after.edges.filter((edge) => !oldEdges.has(key(edge))).map((edge) => edge.id);
  diff.edges.removed = before.edges.filter((edge) => !newEdges.has(key(edge))).map((edge) => edge.id);
  return diff;
}

// Graph model shared by the canvas engine, node cards, editor chrome and graph checks.

export type CanvasNodeKind = 'trigger' | 'action' | 'condition' | 'loop' | 'wait' | 'agent' | 'data' | 'group' | 'note';

/** Run state of a step or an edge: waiting → running → done | error; warning is a config problem before any run. */
export type CanvasRunStatus = 'idle' | 'waiting' | 'running' | 'done' | 'error' | 'warning' | 'skipped';

export type CanvasPortSide = 'top' | 'right' | 'bottom' | 'left';

export type CanvasPortDirection = 'in' | 'out';

/** flow carries the order of steps; the rest carry data and are coloured by type. */
export type CanvasPortType = 'flow' | 'text' | 'number' | 'date' | 'boolean' | 'object' | 'list' | 'tool' | 'memory' | 'knowledge';

export type CanvasEdgePath = 'bezier' | 'smoothstep' | 'step' | 'straight' | 'orthogonal';

export interface CanvasPoint {
  x: number;
  y: number;
}

/** x/y is the screen offset of the graph origin, zoom is the scale. */
export interface CanvasViewport {
  x: number;
  y: number;
  zoom: number;
}

export interface CanvasPort {
  id: string;
  side: CanvasPortSide;
  direction: CanvasPortDirection;
  type?: CanvasPortType;
  label?: string;
  /** More than one edge may attach; outputs default to true, inputs to false. */
  multiple?: boolean;
  /** Centre along the side in px from the node's top (left/right) or left edge (top/bottom); default: spread evenly. */
  offset?: number;
  /** An input the step cannot run without: drawn in danger while nothing is connected. */
  required?: boolean;
}

export interface CanvasNode<TData = unknown> {
  id: string;
  kind: CanvasNodeKind;
  /** Top-left corner in graph coordinates; relative to the parent group when parentId is set. */
  position: CanvasPoint;
  width?: number;
  height?: number;
  ports: readonly CanvasPort[];
  parentId?: string;
  selected?: boolean;
  collapsed?: boolean;
  disabled?: boolean;
  status?: CanvasRunStatus;
  /** Size handles when selected; default: groups and notes (steps keep a fixed width). */
  resizable?: boolean;
  data: TData;
}

export interface CanvasEdge {
  id: string;
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
  path?: CanvasEdgePath;
  label?: string;
  status?: CanvasRunStatus;
  selected?: boolean;
}

export interface CanvasGraph<TData = unknown> {
  nodes: readonly CanvasNode<TData>[];
  edges: readonly CanvasEdge[];
}

/** An edge before it has an id: what a drag from port to port proposes. */
export interface CanvasConnection {
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
}

/** select is not an edit: history replaces the present instead of adding a step. add and update come from the editor around the canvas. */
export type CanvasChangeType = 'select' | 'move' | 'resize' | 'connect' | 'reconnect' | 'delete' | 'paste' | 'layout' | 'label' | 'add' | 'update';

/** Why the graph changed; history uses it to merge and skip steps. */
export interface CanvasChange {
  type: CanvasChangeType;
  nodeIds?: readonly string[];
  edgeIds?: readonly string[];
  /** Changes with the same key in a row within a second are one history step (arrow-key nudges). */
  mergeKey?: string;
}
